actions!(quit_confirm, [Quit]);

fn main() {
    application().run(|cx: &mut App| {
        cx.bind_keys([KeyBinding::new("cmd-q", Quit, None)]); // 需要 import KeyBinding
        cx.on_action(|_: &Quit, cx| cx.quit());
        cx.set_menus([Menu::new("File").items([
            MenuItem::action("Quit", Quit),
        ])]);

        let confirming = Rc::new(Cell::new(false));

        let window_handle = cx.open_window(WindowOptions::default(), |_, cx| {
            cx.new(|_| Editor { dirty: true })
        }).unwrap();

        window_handle.update(cx, |_, window, cx| {
            let confirming = confirming.clone();
            window.on_window_should_close(cx, move |window, cx| {
                if confirming.get() {
                    return true; // 已确认过，放行
                }
